9	// Counts are the contract: how many provider calls a turn makes, and how many tool rounds it actually executes.
10	
11	const ASK_FOR_TOOL: MessageChunk[] = [
12	  {type: 'tool_use', toolCall: {id: 'c', name: 'lookup', input: {}}},
13	  {type: 'stop', stopReason: 'tool_use'},
14	];
15	const FINISH: MessageChunk[] = [
16	  {type: 'text', text: 'Done.'},
17	  {type: 'stop', stopReason: 'end_turn'},
18	];
19	const alwaysTools = (): MessageChunk[] => ASK_FOR_TOOL;
20	const toolThenFinish = (call: number): MessageChunk[] => (call === 0 ? ASK_FOR_TOOL : FINISH);
21	
