// Rounds that report nothing contribute nothing; a turn where nothing reported still reports nothing.
function addRoundUsage(turn: TurnUsage | undefined, round: UsageMetadata | undefined): TurnUsage | undefined {
  if (round === undefined) return turn;
  const summed = turn ?? {inputTokens: 0, outputTokens: 0, totalTokens: 0};
  return {
    inputTokens: summed.inputTokens + round.inputTokens,
    outputTokens: summed.outputTokens + round.outputTokens,
    totalTokens: summed.totalTokens + round.totalTokens,
  };
